  // Spring animation for the central ring
  const ringProgress = spring({
    frame,
    fps,
    config: { damping: 15, stiffness: 80, mass: 0.8 },
  });

  // Gentle ambient pulse for the ring
  const ringPulse = 1 + Math.sin(frame * pulseSpeed * 0.05) * 0.02;
  const finalRingScale = ringProgress * ringPulse;

