        // Calculate the current rotation driven by frame
        const currentRotation = (frame * rotationSpeed) / 50;
        const totalAngle = baseAngle + currentRotation;

        const x = Math.cos(totalAngle) * radius;
        const y = Math.sin(totalAngle) * radius;

